dtsPropsFor.RisoButton:
/** Button label / content. */
children: React.ReactNode;
/** Visual fill. Defaults to 'neutral'. 'gold' = highlight CTA, 'ghost' = outline secondary, 'dark' = Apple sign-in slab (adaptive). */
kind?: 'neutral' | 'primary' | 'blue' | 'green' | 'gold' | 'ghost' | 'dark';
/** Size variant. Defaults to 'default'. */
size?: 'default' | 'large' | 'small';
/** Optional leading inline-SVG icon (e.g. a RisoIcon). */
icon?: React.ReactNode;
/** Stretch to the container width. */
fullWidth?: boolean;
/** Click handler. */
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** Disable the button. */
disabled?: boolean;
/** Native button type. Defaults to 'button'. */
type?: 'button' | 'submit' | 'reset';

dtsPropsFor.RisoCard:
/** Card contents. */
children: React.ReactNode;
/** Hard-shadow depth. Defaults to 'default' (4px). */
shadow?: 'small' | 'default' | 'large';
/** Add hover-lift + press feedback (use for tappable cards). */
interactive?: boolean;
/** Apply the convenience 16px inner padding. */
padded?: boolean;
/** Extra class names to merge (e.g. a screen-specific layout module). */
className?: string;
/** Click handler (for interactive cards). */
onClick?: React.MouseEventHandler<HTMLDivElement>;

dtsPropsFor.RisoChip:
/** Chip label. */
children: React.ReactNode;
/** Selected/active state — inverts the chip to ink fill, cream text. */
on?: boolean;
/** Click handler. */
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** Disable the chip. */
disabled?: boolean;

dtsPropsFor.RisoSegmented:
/** Selectable options, rendered left-to-right. Each: { value, label }. */
options: ReadonlyArray<{ value: string | number; label: React.ReactNode }>;
/** Currently-selected value. */
value: string | number;
/** Called with the chosen value when a segment is pressed. */
onChange: (value: string | number) => void;
/** 'card' (default) = bordered buttons, blue active. 'pill' = compact toggle, ink active. */
variant?: 'card' | 'pill';
/** Accessible group label — REQUIRED (a role="group" needs an accessible name). */
'aria-label': string;

dtsPropsFor.RisoSectionLabel:
/** Eyebrow text (rendered uppercase, tracked). */
children: React.ReactNode;
/** 'section' (default) = quiet muted eyebrow over a card. 'kicker' = loud red eyebrow over a headline. */
variant?: 'section' | 'kicker';

dtsPropsFor.RisoIcon:
/** Which glyph to render. */
name: 'boards' | 'home' | 'tasks' | 'you' | 'plus' | 'back' | 'check' | 'sun' | 'moon' | 'share' | 'sync' | 'sliders' | 'repeat' | 'grid' | 'flame' | 'shield' | 'bell' | 'logout' | 'chevron' | 'edit' | 'trash' | 'dots';
/** Pixel size (width = height). Omit to inherit via CSS. Strokes inherit currentColor. */
size?: number;
/** Accessible label. Omit for a decorative icon (renders aria-hidden). */
'aria-label'?: string;
/** Extra class names for the <svg>. */
className?: string;

dtsPropsFor.RisoBadge:
/** Status this badge represents (sets the color). */
kind: 'active' | 'completed' | 'draft' | 'expiring' | 'archived';
/** Badge label (rendered uppercase). */
children: React.ReactNode;
